const RESPONSE_GRACE_MS=24*60*60*1000;
function computeResponseRates(msgs,crewMsgs,crews){function rateFor(threads,triggerFn,replyFn){var total=0,responded=0;threads.forEach(function(arr){var lastIdx=-1;arr.forEach(function(m,i){if(triggerFn(m))lastIdx=i;});if(lastIdx<0)return;var replied=arr.slice(lastIdx+1).some(replyFn);if(!replied){var _t=arr[lastIdx]&&arr[lastIdx].ts;if(!_t||(Date.now()-_t)<RESPONSE_GRACE_MS)return;}total++;if(replied)responded++;});return total?Math.round(responded/total*100):null;}var mine=function(m){return m.from==="me";};var rates={};var allThreads=Object.keys(msgs||{}).map(function(k){return msgs[k];}).concat(Object.keys(crewMsgs||{}).map(function(k){return crewMsgs[k];}));var meRate=rateFor(allThreads,function(m){return !mine(m);},mine);if(meRate!=null)rates[0]=meRate;var ids=new Set();Object.keys(msgs||{}).forEach(function(k){ids.add(Number(k));});(crews||[]).forEach(function(cr){(cr.members||[]).forEach(function(m){if(m.climberId!==0)ids.add(m.climberId);});});ids.forEach(function(id){var threads=[];if(msgs&&msgs[id])threads.push(msgs[id]);(crews||[]).forEach(function(cr){if((cr.members||[]).some(function(m){return m.climberId===id;})&&crewMsgs&&crewMsgs[cr.id])threads.push(crewMsgs[cr.id]);});var r=rateFor(threads,mine,function(m){return m.from===id;});if(r!=null)rates[id]=r;});return rates;}
