function gradeVal(r){var c=catOf(r);var gl=ADDR_GRADES[c]||ADDR_YDS;var i=gl.indexOf(r&&r.grade);if(i<0)return Number.MAX_SAFE_INTEGER;var so=_GRADE_SCALE_ORDER[c];return (so!=null?so:9)*1000+i;}
