function sunReadout(aspect,disc){var _open=["scrambling","mountaineering","alpine"].indexOf(disc)>=0;if(_open){var _snowy=disc==="mountaineering"||disc==="alpine";var _dh=(function(){var n=new Date();return n.getHours()+n.getMinutes()/60;})();var _day=_dh>=6&&_dh<20.5;if(!_day)return {sunNow:false,line:(_snowy?"Open snow and glacier with no shade once the sun is up — direct sun for most of the daylight hours. The snow throws back intense UV and glare and softens by midday, so climb on a hard overnight freeze and be off the upper slopes early.":"Open terrain with little natural shade — direct sun for most of the daylight hours. Carry sun protection and water, and start early to stay ahead of the afternoon heat.")};return {sunNow:true,line:_snowy?"Where the line crosses snow or glacier, expect direct sun for most of the day. The snow throws back intense UV and glare and softens by midday, so climb on a hard overnight freeze and be off the upper slopes early.":"Open terrain with little natural shade — in direct sun for most of the day. Carry sun protection and water, and start early to stay ahead of the afternoon heat."};}const d=aspectDirs(aspect),now=new Date(),h=now.getHours()+now.getMinutes()/60;/* "varied"/"varies"/"Variable"/"Mixed" — 13 live rows — parse to no direction and would otherwise fall into the north-facing branch below and be told they never catch sun. Unknown is not north-facing. */if(!d.size)return {sunNow:null,line:"The aspect on file for this route isn't specific enough to work out sun and shade timing. Check the route description or a recent trip report."};const dir=d.has("S")?"S":d.has("E")?"E":d.has("W")?"W":d.has("N")?"N":"";const win={E:[6,12.5],S:[8.5,16.5],W:[12,20.5]}[dir];const fmt=t=>{const hh=Math.floor(t),mm=Math.round((t-hh)*60),ap=hh>=12?"pm":"am",h12=hh%12||12;return mm?`${h12}:${String(mm).padStart(2,"0")}${ap}`:`${h12}${ap}`;};if(!win)return {sunNow:false,line:"Shaded all day — this wall never catches direct sun, so it stays cool in summer and cold in winter."};const sunNow=h>=win[0]&&h<win[1];let line;if(sunNow)line=`Direct sun until about ${fmt(win[1])}, when it drops into shade. Want shade? Get on it before ~${fmt(win[0])}.`;else if(h<win[0])line=`Shaded now and stays shaded until about ${fmt(win[0])}, then sun until ~${fmt(win[1])} — a good morning-shade window.`;else line=`Shaded now and for the rest of the day — the sun came off it around ${fmt(win[1])}.`;return {sunNow,line};}
function sunNow(aspect){const d=aspectDirs(aspect);const dir=d.has("S")?"S":d.has("E")?"E":d.has("W")?"W":d.has("N")?"N":"";if(!dir)return null;if(dir==="N")return false;const now=new Date(),h=now.getHours()+now.getMinutes()/60,win={E:[6,12.5],S:[8.5,16.5],W:[12,20.5]}[dir];return win?(h>=win[0]&&h<=win[1]):false;}
// Shape describes the OUTING, so read only fields that describe it as a whole. `descent`
// is excluded deliberately: descent prose uses "traverse" as a verb ("reverse the ridge
// traverse to camp"), which classified 78 ordinary out-and-back WA routes as point-to-point
// and silently dropped them from the shape filter. Word boundaries for the same reason.
function shapeOf(r){const t=((r.name||"")+" "+(r.blurb||"")+" "+(r.summary||"")).toLowerCase();if(/\bloop\b/.test(t))return "loop";if(/\bpoint.to.point\b|\btraverse\b|\bthru.?hike\b/.test(t))return "point";return "outback";}
function passesFilters(r,f){
  if(f.features&&f.features.length&&!(r.features||[]).some(x=>f.features.includes(x)))return false;
  if(f.aspect&&f.aspect.length){const dirs=aspectDirs(r.aspect);if(!f.aspect.some(d=>dirs.has(d)))return false;}
  if((f.gradeMin&&f.gradeMin!=="any")||(f.gradeMax&&f.gradeMax!=="any")){const fk=(f.gradeMin&&f.gradeMin!=="any")?f.gradeMin:f.gradeMax;const sys=Object.keys(GRADE_BANDS).find(k=>GRADE_BANDS[k].some(b=>b[0]===fk));if(!sys)return false;const routeSys=routeGradeSystem(r);if(routeSys&&routeSys!==sys)return false;if(routeSys===sys){const bands=GRADE_BANDS[sys],N=bands.length-1,ord=k=>bands.findIndex(b=>b[0]===k),idx=routeBandIdx(sys,r.grade);if(idx>=0){const lo=(f.gradeMin&&f.gradeMin!=="any")?ord(f.gradeMin):1,hi=(f.gradeMax&&f.gradeMax!=="any")?ord(f.gradeMax):N;if(idx<lo||idx>hi)return false;}}}
  if(f.pitches&&f.pitches!=="any"){const p=r.pitches||0;if(f.pitches==="single"&&p!==1)return false;if(f.pitches==="multi"&&p<2)return false;}if(f.month!==undefined&&f.month!=="any"){if(!seasonMonths(r.season).has(f.month))return false;}if(f.verifiedOnly&&!(r.verif&&r.verif.status==="verified"))return false;if(f.permitFree&&!/^none|no permit/i.test((r.permits||"").trim()))return false;if(f.classicOnly&&!r.classic)return false;if(f.approach<28){if((r.distKm||0)>f.approach)return false;}if(f.cellOnly){const cm=rxOf(r.id).comms;if(!cm||cm.coverage==="none")return false;}if(f.minStars||f.minReports){const acts=r.activity||[],cnt=acts.length,avg=cnt?acts.reduce((s,a)=>s+(a.stars||0),0)/cnt:0;if(f.minStars&&avg<f.minStars)return false;if(f.minReports&&cnt<f.minReports)return false;}if(f.maxMi&&f.maxMi<500&&haveMyLoc()){const mtn=MOUNTAINS.find(m=>m.id===r.mountainId);if(mtn&&distMiles(ME,mtn)>f.maxMi)return false;}
  if(f.rock&&f.rock.length&&!f.rock.some(rk=>(r.rockType||"").includes(rk)))return false;if(f.descent&&f.descent!=="any"){const hasRap=r.rappels!=null;if(f.descent==="rappel"&&!hasRap)return false;if(f.descent==="walkoff"&&hasRap)return false;}if(f.commit&&f.commit!=="any"&&r.commitment!==f.commit)return false;if(f.length&&f.length!=="any"){const ft=r.routeFt||0;/* 200-or-less / 201-and-up: the old pair met at 200 and disagreed about it. Kept in step with lenMatch in RouteFinder. */if(f.length==="u200"&&!(ft<=200))return false;if(f.length==="200"&&!(ft>=201&&ft<600))return false;if(f.length==="600"&&!(ft>=600&&ft<1500))return false;if(f.length==="1500"&&!(ft>=1500))return false;}if(f.gain&&f.gain!=="any"){const g=r.gainFt||0;if(f.gain==="u1000"&&!(g>0&&g<1000))return false;if(f.gain==="1000"&&!(g>=1000&&g<2500))return false;if(f.gain==="2500"&&!(g>=2500))return false;}if(f.shape&&f.shape!=="any"){if(shapeOf(r)!==f.shape)return false;}if(f.trs&&!r.trs)return false;if(f.sun&&f.sun!=="any"){const ss=sunNow(r.aspect);if(ss===null)return false;if(f.sun==="sun"&&ss!==true)return false;if(f.sun==="shade"&&ss!==false)return false;}return true;
}
const LVL={Beginner:{color:C.green,bg:C.greenBg},Intermediate:{color:C.amber,bg:C.amberBg},Advanced:{color:C.blue,bg:C.blueBg},Expert:{color:C.purple,bg:C.purpleBg}};
const LEVEL_DESC={Beginner:"New to climbing — building fundamentals on easier, well-protected terrain.",Intermediate:"Comfortable on moderate routes — leads or follows mid-grade sport, trad, and scrambles.",Advanced:"Confident on hard, technical terrain — leads steep sport and committing trad.",Expert:"Highly experienced across disciplines — operates on demanding, serious objectives."};
