  const [adding,setAdding]=useState(false);
  const [nType,setNType]=useState("AMGA Single Pitch Instructor");
  const [nNum,setNNum]=useState("");const [nExp,setNExp]=useState("");
  const [rate,setRate]=useState("450");const [groupMax,setGroupMax]=useState("2");
