    if(mode==="route"&&(!selectedRoute||!c.objectiveIds.includes(selectedRoute)))return false;if(mode==="area"){if(areaBy==="near"){if(radiusMi<9000&&haveMyLoc()&&distMiles(ME,c)>radiusMi)return false;}else{const reg=areaId||areaState||areaCountry;if(reg&&!c.objectiveIds.some(id=>{const r=ROUTES.find(x=>x.id===id);return r&&inArea(r.mountainId,reg);}))return false;}}
