  {sf("commit")?<div><div style={lab}>{"Time commitment"}</div><div style={{display:"flex",gap:6,flexWrap:"wrap"}}>{ADDR_COMMIT.map(o=>{const on=commit===o;return <button key={o} onClick={()=>setCommit(on?"":o)} style={sm(on)}>{o}</button>;})}</div></div>:null}
  {sf("approach")?<div><div style={lab}>{"Approach"}</div><div style={{display:"flex",gap:6,flexWrap:"wrap"}}>{[["u1","< 1 mi"],["1to3","1–3 mi"],["3to6","3–6 mi"],["6plus","6+ mi"]].map(o=>{const on=approach===o[0];return <button key={o[0]} onClick={()=>setApproach(on?"":o[0])} style={sm(on)}>{o[1]}</button>;})}</div></div>:null}
  {sf("season")?<div><div style={lab}>{"Best season"}</div><div style={{display:"flex",gap:6,flexWrap:"wrap"}}>{["Spring","Summer","Fall","Winter","Year-round"].map(o=>{const on=season===o;return <button key={o} onClick={()=>setSeason(on?"":o)} style={sm(on)}>{o}</button>;})}</div></div>:null}
  {sf("descent")?<div><div style={lab}>{"Descent"}</div><div style={{display:"flex",gap:6}}>{[["rappel","Rappel"],["walkoff","Walk-off"]].map(o=>{const on=descent===o[0];return <button key={o[0]} onClick={()=>setDescent(on?"":o[0])} style={chip(on)}>{o[1]}</button>;})}</div></div>:null}
