function itinDraftToStructured(itin){var days=((itin&&itin.days)||[]).map(function(d,i){return {n:i+1,title:d.title||"",objective:d.objective||"",gainFt:d.gainFt?parseInt(d.gainFt):null,lossFt:d.lossFt?parseInt(d.lossFt):null,hours:d.hours?(_r1.test(String(d.hours))?String(d.hours).trim():parseFloat(d.hours)):null,miles:d.miles?parseFloat(d.miles):null,packLb:d.packLb?parseInt(d.packLb):null,note:d.note||"",schedule:(d.schedule||[]).filter(function(st){return st.time||st.label||st.detail;}).map(function(st){return {time:st.time||"",label:st.label||"",detail:st.detail||""};})};}).filter(function(d){return d.title||d.objective||d.note||d.gainFt||d.lossFt||d.hours||d.miles||d.packLb||d.schedule.length;});return {days:days,cal:(itin&&itin.cal)||undefined,totalNote:(itin&&itin.totalNote)||undefined};}

var PACE_TIERS=[["slow","Slower pace",1.35],["medium","Medium pace",1],["fast","Faster pace",0.75]];
// Day hours are authored as ranges ("3-4.5") wherever a real party's time is
