function scaleItinPace(itin,mult){return {cal:itin.cal,totalNote:itin.totalNote,days:(itin.days||[]).map(function(d){return Object.assign({},d,{hours:scaleHours(d.hours,mult)});})};}
function getAvailableItineraries(route){var out=[];var canon=(route&&route.itinerary&&route.itinerary.days&&route.itinerary.days.length)?route.itinerary:null;if(canon){PACE_TIERS.forEach(function(p){var scaled=scaleItinPace(canon,p[2]);var totH=scaled.days.reduce(function(s,d){return s+hoursNum(d.hours);},0);out.push({key:"pace_"+p[0],label:p[1]+(p[0]==="medium"?" (recommended)":""),sub:scaled.days.length+" day"+(scaled.days.length!==1?"s":"")+(totH?" · ~"+(Math.round(totH*10)/10)+" hr total":""),itin:scaled});});}(route&&route.activity||[]).forEach(function(a,i){if(a&&a.itinerary&&a.itinerary.days&&a.itinerary.days.length){out.push({key:"log"+i,label:(a.user||"A climber")+"’s plan",sub:(a.date?a.date+" · ":"")+a.itinerary.days.length+" day"+(a.itinerary.days.length!==1?"s":""),itin:a.itinerary});}});return out;}
function itinToText(it,routeName){var lines=[(routeName||"Route")+" — day-by-day plan",""];(it&&it.days||[]).forEach(function(d,i){lines.push("Day "+(d.n||i+1)+(d.title?": "+d.title:""));if(d.objective)lines.push("  Objective: "+d.objective);var stats=[];if(d.gainFt)stats.push("Gain "+d.gainFt+" ft");if(d.lossFt)stats.push("Loss "+d.lossFt+" ft");if(d.hours)stats.push(d.hours+" hr");if(d.miles)stats.push(d.miles+" mi");if(d.packLb)stats.push(d.packLb+" lb pack");if(stats.length)lines.push("  "+stats.join(" · "));if(d.note)lines.push("  "+d.note);(d.schedule||[]).forEach(function(st){lines.push("  "+(st.time?st.time+" — ":"")+st.label+(st.detail?" ("+st.detail+")":""));});lines.push("");});return lines.join("\n");}
var TIME_PRESETS=["3:00 AM","5:00 AM","7:00 AM","9:00 AM","12:00 PM","3:00 PM","6:00 PM"];
function ItineraryEditor({itin,onChange}){
  const fld={width:"100%",padding:"9px 11px",borderRadius:9,border:"1px solid "+C.border,background:C.surface,color:C.text,fontSize:14,boxSizing:"border-box",outline:"none"};
  const days=(itin&&itin.days&&itin.days.length)?itin.days:[blankItinDay()];
  const setDays=function(fn){onChange(Object.assign({},itin,{days:fn(days)}));};
  const setDayField=function(i,k,v){setDays(function(ds){var nd=ds.slice();nd[i]=Object.assign({},nd[i],{[k]:v});return nd;});};
  const addDay=function(){setDays(function(ds){return ds.concat([blankItinDay()]);});};
  const rmDay=function(i){setDays(function(ds){return ds.filter(function(_,j){return j!==i;});});};
  const addSched=function(di,t){setDays(function(ds){var nd=ds.slice();nd[di]=Object.assign({},nd[di],{schedule:(nd[di].schedule||[]).concat([{time:t||"",label:"",detail:""}])});return nd;});};
  const setSchedField=function(di,si,k,v){setDays(function(ds){var nd=ds.slice();var sched=(nd[di].schedule||[]).slice();sched[si]=Object.assign({},sched[si],{[k]:v});nd[di]=Object.assign({},nd[di],{schedule:sched});return nd;});};
  const rmSched=function(di,si){setDays(function(ds){var nd=ds.slice();nd[di]=Object.assign({},nd[di],{schedule:(nd[di].schedule||[]).filter(function(_,j){return j!==si;})});return nd;});};
  return <div>{days.map(function(d,di){return <div key={di} style={{background:C.surface,border:"1px solid "+C.border,borderRadius:10,padding:"10px 11px",marginBottom:8}}>
    <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:7}}><span style={{fontSize:12.5,fontWeight:700,color:C.blue}}>{"Day "+(di+1)}</span>{days.length>1?<button onClick={function(){rmDay(di);}} aria-label="Remove day" style={{background:"none",border:"none",color:C.textMuted,fontSize:17,cursor:"pointer",lineHeight:1,padding:0}}>{"×"}</button>:null}</div>
    <input aria-label="Day title" value={d.title} onChange={function(e){setDayField(di,"title",e.target.value);}} placeholder="Day title (e.g. Approach to base camp)" style={Object.assign({},fld,{marginBottom:6})}/>
    <input aria-label="Objective (optional)" value={d.objective} onChange={function(e){setDayField(di,"objective",e.target.value);}} placeholder="Objective (optional)" style={Object.assign({},fld,{marginBottom:6})}/>
    <div style={{display:"flex",gap:6,marginBottom:6}}>
      <div style={{flex:1}}><div style={{fontSize:10.5,fontWeight:700,color:C.textMuted,marginBottom:3}}>GAIN (FT)</div><input aria-label="Gain (ft)" value={d.gainFt} onChange={function(e){setDayField(di,"gainFt",intOnly(e.target.value));}} inputMode="numeric" placeholder="0" style={fld}/></div>
      <div style={{flex:1}}><div style={{fontSize:10.5,fontWeight:700,color:C.textMuted,marginBottom:3}}>LOSS (FT)</div><input aria-label="Loss (ft)" value={d.lossFt} onChange={function(e){setDayField(di,"lossFt",intOnly(e.target.value));}} inputMode="numeric" placeholder="0" style={fld}/></div>
      <div style={{flex:1}}><div style={{fontSize:10.5,fontWeight:700,color:C.textMuted,marginBottom:3}}>HOURS</div><input aria-label="Hours" value={d.hours} onChange={function(e){setDayField(di,"hours",e.target.value.replace(/[^0-9.]/g,""));}} inputMode="decimal" placeholder="0" style={fld}/></div>
    </div>
    <div style={{display:"flex",gap:6,marginBottom:6}}>
      <div style={{flex:1}}><div style={{fontSize:10.5,fontWeight:700,color:C.textMuted,marginBottom:3}}>DISTANCE (MI)</div><input aria-label="Distance (mi)" value={d.miles} onChange={function(e){setDayField(di,"miles",e.target.value.replace(/[^0-9.]/g,""));}} inputMode="decimal" placeholder="0" style={fld}/></div>
      <div style={{flex:1}}><div style={{fontSize:10.5,fontWeight:700,color:C.textMuted,marginBottom:3}}>PACK WEIGHT (LB)</div><input aria-label="Pack weight (lb)" value={d.packLb} onChange={function(e){setDayField(di,"packLb",intOnly(e.target.value));}} inputMode="numeric" placeholder="0" style={fld}/></div>
    </div>
    <textarea aria-label="Notes for this day" value={d.note} onChange={function(e){setDayField(di,"note",e.target.value);}} rows={2} placeholder="Notes for this day" style={Object.assign({},fld,{resize:"vertical",marginBottom:6})}/>
    <div style={{fontSize:11,fontWeight:700,color:C.textMuted,marginBottom:5}}>SCHEDULE (optional)</div>
    {(d.schedule||[]).map(function(st,si){return <div key={si} style={{marginBottom:6,paddingBottom:si<((d.schedule||[]).length-1)?6:0,borderBottom:si<((d.schedule||[]).length-1)?"1px solid "+C.borderLight:"none"}}><div style={{display:"flex",gap:5,marginBottom:4}}><input aria-label="Time" value={st.time} onChange={function(e){setSchedField(di,si,"time",e.target.value);}} placeholder="5:00 AM" style={Object.assign({},fld,{width:76,flex:"none"})}/><input aria-label="Leave trailhead" value={st.label} onChange={function(e){setSchedField(di,si,"label",e.target.value);}} placeholder="Leave trailhead" style={Object.assign({},fld,{flex:1})}/><button onClick={function(){rmSched(di,si);}} aria-label="Remove schedule entry" style={{background:"none",border:"none",color:C.textMuted,fontSize:17,cursor:"pointer",lineHeight:1,padding:0,flexShrink:0}}>{"×"}</button></div><input aria-label="Detail (optional)" value={st.detail} onChange={function(e){setSchedField(di,si,"detail",e.target.value);}} placeholder="Detail (optional)" style={fld}/></div>;})}
    <div style={{display:"flex",gap:5,flexWrap:"wrap"}}>{TIME_PRESETS.map(function(t){return <button key={t} onClick={function(){addSched(di,t);}} style={{padding:"5px 9px",borderRadius:7,border:"1px solid "+C.border,background:C.surface,color:C.textSub,fontSize:11,fontWeight:600,cursor:"pointer"}}>{t}</button>;})}<button onClick={function(){addSched(di);}} style={{padding:"5px 10px",borderRadius:7,border:"1px dashed "+C.border,background:C.card,color:C.textSub,fontSize:11.5,fontWeight:600,cursor:"pointer"}}>{"+ Custom time"}</button></div>
  </div>;})}<button onClick={addDay} style={{width:"100%",padding:"9px",borderRadius:9,border:"1px dashed "+C.blue,background:C.blueBg,color:C.blue,fontSize:13,fontWeight:700,cursor:"pointer"}}>{"+ Add day"}</button></div>;
}
function WaypointMapPicker({waypoints,activeIdx,onPick,peakCoord}){
  const mapDiv=useRef(null),mapRef=useRef(null),markersRef=useRef([]),tileRef=useRef(null);
  const [ready,setReady]=useState(false),[mapFail,setMapFail]=useState(false);
  const [baseLayer,setBaseLayer]=useState("sat");
  const wc=WP_COLORS;
  const pickRef=useRef(onPick);pickRef.current=onPick;
  useEffect(function(){
    let cancelled=false;
    const init=function(){
      if(cancelled||!mapDiv.current||mapRef.current||!window.L)return;
      const L=window.L;const map=L.map(mapDiv.current,{attributionControl:false});
      applyBaseLayer(map,tileRef,baseLayer);
      const withCoords=(waypoints||[]).filter(function(w){return w&&w.lat!=null&&w.lng!=null&&!isNaN(w.lat)&&!isNaN(w.lng);});
      if(withCoords.length){map.fitBounds(L.latLngBounds(withCoords.map(function(w){return [w.lat,w.lng];})).pad(0.35));}
      else if(peakCoord&&peakCoord.lat!=null){map.setView([peakCoord.lat,peakCoord.lng],15);}
      else{map.setView([39.5,-98.5],4);}
      map.on("click",function(e){pickRef.current&&pickRef.current(e.latlng.lat,e.latlng.lng);});
      mapRef.current=map;setReady(true);
      setTimeout(function(){try{map.invalidateSize();}catch(e){}},150);
    };
    loadLeaflet(init,function(){setMapFail(true);});
    const ft=setTimeout(function(){if(!cancelled&&!mapRef.current)setMapFail(true);},9000);
    return function(){cancelled=true;clearTimeout(ft);if(mapRef.current){try{mapRef.current.remove();}catch(e){}mapRef.current=null;tileRef.current=null;}};
  },[]);
  useEffect(function(){if(!mapRef.current)return;applyBaseLayer(mapRef.current,tileRef,baseLayer);},[baseLayer]);
  useEffect(function(){
    if(!mapRef.current||!window.L)return;
    const L=window.L,map=mapRef.current;
    markersRef.current.forEach(function(m){try{map.removeLayer(m);}catch(e){}});markersRef.current=[];
    if(peakCoord&&peakCoord.lat!=null){
      const pk=L.circleMarker([peakCoord.lat,peakCoord.lng],{radius:5,color:C.orange,weight:2,fillColor:C.orange,fillOpacity:0.15,dashArray:"2,2"});
      pk.bindTooltip(peakCoord.name||"Peak location",{direction:"top"});pk.addTo(map);markersRef.current.push(pk);
    }
    (waypoints||[]).forEach(function(w,i){
      if(!w||w.lat==null||w.lng==null||isNaN(w.lat)||isNaN(w.lng))return;
      const isActive=i===activeIdx;
      const mk=L.circleMarker([w.lat,w.lng],{radius:isActive?9:6,color:isActive?C.blue:"#ffffff",weight:isActive?3:2,fillColor:wc[wpType(w)]||C.textSub,fillOpacity:1});
      mk.bindTooltip((w.type||"")+(w.name?": "+w.name:""),{direction:"top"});mk.addTo(map);markersRef.current.push(mk);
    });
  },[waypoints,activeIdx,peakCoord]);
  return <div style={{position:"relative",marginBottom:10}}>
    <div ref={mapDiv} style={{height:190,borderRadius:9,border:"1px solid "+C.border,overflow:"hidden",background:"#0a0f1a",cursor:"crosshair"}}/>
    {!ready?<div style={{position:"absolute",inset:0,display:"flex",alignItems:"center",justifyContent:"center",color:C.textMuted,fontSize:12,pointerEvents:"none",textAlign:"center",padding:16}}>{mapFail?"Map couldn't load — enter coordinates manually below.":"Loading map…"}</div>:null}
    {ready?<div style={{position:"absolute",top:7,left:7,zIndex:1000,display:"flex",gap:3}}>{[["sat","Sat"],["topo","Topo"],["street","St"]].map(([k,lbl])=><button key={k} onClick={()=>setBaseLayer(k)} style={{padding:"4px 7px",borderRadius:6,border:"1px solid "+(baseLayer===k?C.blue:C.border),background:baseLayer===k?C.blueBg:C.surface,color:baseLayer===k?C.blue:C.textSub,fontSize:10,fontWeight:700,cursor:"pointer",boxShadow:"0 2px 6px rgba(0,0,0,0.4)"}}>{lbl}</button>)}</div>:null}
    {ready?<div style={{position:"absolute",bottom:7,left:7,right:7,background:"rgba(13,17,23,0.85)",borderRadius:7,padding:"4px 8px",fontSize:11,color:C.text,textAlign:"center",pointerEvents:"none"}}>{"Tap the map to place Waypoint "+((activeIdx!=null?activeIdx:0)+1)}</div>:null}
  </div>;
}

function Contributions({items,onClose,onOpenRoute,session,routeById}){
  const ST={review:{lbl:"In review",icon:"⚠",col:C.amber,bg:C.amberBg},community:{lbl:"Confirming",icon:"👥",col:C.blue,bg:C.blueBg},added:{lbl:"Added — live",icon:"✓",col:C.green,bg:C.greenBg},confirmed:{lbl:"You confirmed",icon:"✓",col:C.green,bg:C.greenBg},verified:{lbl:"Live & verified",icon:"✓",col:C.green,bg:C.greenBg}};
  const uid=(USE_DB&&session&&session.user)?session.user.id:null;
  const dbMine=useMyContributions(uid);
  const dbAreaIds=(dbMine.data||[]).map(function(row){return row.routes&&row.routes.area_id;}).filter(Boolean);
  const dbAreaPaths=useAreaPaths(dbAreaIds);
  const dbItems=(uid&&dbMine.data)?dbMine.data.map(function(row){var rn=row.routes&&row.routes.name;var rt=routeById?routeById(row.route_id):ROUTES.find(function(r){return r.id===row.route_id;});var cv=row.value==null?"":Array.isArray(row.value)?row.value.join(", "):(typeof row.value==="object"?"updated":String(row.value));var fl=String(row.field||"").replace(/([A-Z])/g," $1").replace(/^./,function(s){return s.toUpperCase();});var areaId=row.routes&&row.routes.area_id;var dbPath=areaId&&dbAreaPaths[areaId];var area=rt?areaPathNames(rt.mountainId):"";if(!area&&dbPath&&dbPath.length)area=dbPath.map(function(a){return a.name;}).join(" › ");return {type:"edit",title:(rn||(rt&&rt.name)||"Route")+(fl?" — "+fl:""),area:area,meta:"Suggested: "+cv,status:"community",when:ago(row.created_at),confirms:undefined,routeObj:rt||undefined};}):null;
  const list=dbItems||items;
  return <div onClick={onClose} role="dialog" aria-modal="true" aria-label="Your contributions" style={{position:"fixed",inset:0,background:"rgba(0,0,0,0.85)",zIndex:900,display:"flex",alignItems:"flex-start",justifyContent:"center",padding:"16px 12px",overflowY:"auto",overscrollBehavior:"contain"}}>
    <div onClick={function(e){e.stopPropagation();}} style={{background:C.surface,borderRadius:18,width:"100%",maxWidth:460,border:"1px solid "+C.border,overflow:"hidden",display:"flex",flexDirection:"column",maxHeight:"92vh"}}>
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",padding:"14px 16px",borderBottom:"1px solid "+C.border,flexShrink:0}}><div style={{fontSize:16,fontWeight:700}}>Your contributions</div><button onClick={onClose} aria-label="Close" style={{background:C.borderLight,border:"none",color:C.textSub,borderRadius:8,width:36,height:36,fontSize:20,cursor:"pointer"}}>{"✕"}</button></div>
      <div style={{minHeight:0,padding:16,overflowY:"auto",flex:1}}><div style={{fontSize:12.5,color:C.textSub,lineHeight:1.55,background:C.card,border:"1px solid "+C.border,borderRadius:11,padding:"10px 12px",marginBottom:12}}>{"Routes you’ve added and edits you’ve suggested. Each one earns trust as climbers confirm it — and you’re credited as the contributor."}</div>
      {list.length?list.map(function(c,i){var st=ST[c.status]||ST.review;var clickable=!!(c.routeObj&&onOpenRoute);return <div key={i} onClick={clickable?function(){onOpenRoute(c.routeObj);onClose();}:undefined} style={{background:C.card,border:"1px solid "+C.border,borderRadius:12,padding:"11px 13px",marginBottom:9,cursor:clickable?"pointer":"default"}}><div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:4}}><span style={{fontSize:13,fontWeight:800,letterSpacing:0.4,color:C.text,textTransform:"uppercase",borderLeft:"3px solid "+C.blue,paddingLeft:9}}>{c.type==="route"?"Route added":(c.type==="confirm"?"Data confirmed":"Edit suggested")}</span><span style={{fontSize:12,color:C.textMuted}}>{c.when}</span></div><div style={{fontSize:14.5,fontWeight:700}}>{c.title}</div><div style={{fontSize:12,color:C.textSub,marginTop:1}}>{c.area}</div>{c.meta?<div style={{fontSize:12,color:C.textMuted,marginTop:2}}>{c.meta}</div>:null}<div style={{marginTop:8,display:"flex",justifyContent:"space-between",alignItems:"center"}}><span style={{display:"inline-flex",alignItems:"center",gap:5,fontSize:11.5,fontWeight:700,color:st.col,background:st.bg,border:"1px solid "+st.col+"55",borderRadius:20,padding:"3px 10px"}}><ActionIcon name={{review:"alert",community:"user",added:"check",confirmed:"check",verified:"check"}[c.status]||"alert"} size={11} color={st.col}/>{st.lbl+(c.confirms?(" · "+c.confirms+" confirmation"+(c.confirms!==1?"s":"")):"")}</span>{clickable?<span style={{fontSize:11.5,color:C.blue,fontWeight:700}}>Edit →</span>:null}</div></div>;}):<div style={{textAlign:"center",padding:"30px 16px",color:C.textMuted,fontSize:13,lineHeight:1.6}}>{"Nothing yet — add a climb or suggest a fix on any route, and it’ll show up here with its review status."}</div>}
      </div>
    </div>
  </div>;
}
function SunCorrect({route,onClose,onSubmit}){
  const [vote,setVote]=useState("more");const [note,setNote]=useState("");
  const opts=[["more","More sun than shown",C.amber,C.amberBg],["accurate","About as described",C.green,C.greenBg],["less","More shade than shown",C.blue,C.blueBg]];
  return <div onClick={onClose} role="dialog" aria-modal="true" aria-label="Sun on this route" style={{position:"fixed",inset:0,background:"rgba(0,0,0,0.6)",display:"flex",alignItems:"flex-end",justifyContent:"center",zIndex:60}}><div onClick={e=>e.stopPropagation()} style={{background:C.surface,width:"100%",maxWidth:440,borderRadius:"18px 18px 0 0",border:"1px solid "+C.border,maxHeight:"90vh",overflowY:"auto",overscrollBehavior:"contain"}}><div style={{display:"flex",justifyContent:"space-between",alignItems:"center",padding:"14px 16px",borderBottom:"1px solid "+C.border}}><div style={{fontSize:15,fontWeight:800,color:C.text}}>Sun on this route</div><button onClick={onClose} aria-label="Close" style={{background:C.card,border:"1px solid "+C.border,color:C.textSub,borderRadius:8,width:36,height:36,fontSize:20,cursor:"pointer"}}>✕</button></div><div style={{padding:"14px 16px"}}><div style={{fontSize:13,fontWeight:700,color:C.text,marginBottom:2}}>{route.name}</div><div style={{fontSize:12,color:C.textSub,lineHeight:1.5,marginBottom:14}}>Climbed it? Tell the next party what the sun is really like. Your report joins this route's community sun notes and helps correct the forecast.</div><div style={{fontSize:12,fontWeight:800,letterSpacing:0.3,color:C.textMuted,marginBottom:7}}>HOW WAS THE SUN?</div><div style={{display:"flex",flexDirection:"column",gap:7,marginBottom:14}}>{opts.map(o=>{const on=vote===o[0];return <button key={o[0]} onClick={()=>setVote(o[0])} style={{textAlign:"left",padding:"10px 12px",borderRadius:10,border:"1px solid "+(on?o[2]:C.border),background:on?o[3]:C.card,color:on?o[2]:C.textSub,fontSize:13.5,fontWeight:600,cursor:"pointer"}}>{o[1]}</button>;})}</div><div style={{fontSize:12,fontWeight:800,letterSpacing:0.3,color:C.textMuted,marginBottom:7}}>NOTES (optional)</div><textarea aria-label="Notes (optional)" value={note} onChange={e=>setNote(e.target.value)} rows={3} placeholder="e.g. Full sun on the upper glacier all afternoon — bring glacier glasses and sunscreen." style={{width:"100%",padding:"9px 11px",borderRadius:10,border:"1px solid "+C.border,background:C.card,color:C.text,fontSize:13,boxSizing:"border-box",resize:"vertical",fontFamily:"inherit",lineHeight:1.5,outline:"none"}}/></div><div style={{padding:"12px 16px",borderTop:"1px solid "+C.border}}><button onClick={()=>{onSubmit({vote:vote,note:note});onClose();}} style={{width:"100%",padding:"11px",borderRadius:10,border:"none",background:C.blueSolid,color:"#fff",fontSize:14,fontWeight:700,cursor:"pointer"}}>Submit sun report</button></div></div></div>;
}

function SearchSplit({onArea,onRoute,selected,defaultMode,addArea,compact,scope,query,onQuery,onView}){
  const [mode,setMode]=useState(defaultMode||"areas");
  const [iq,setIq]=useState("");const q=query!==undefined?query:iq;const setQ=onQuery||setIq;
  const qq=q.trim();const sel=selected||[];
  const tab=on=>({flex:1,padding:"7px 0",textAlign:"center",fontSize:12.5,fontWeight:700,cursor:"pointer",borderRadius:7,background:on?C.blueSolid:"transparent",color:on?"#fff":C.textSub});
  const fld={width:"100%",padding:"10px 12px",borderRadius:9,border:"1px solid "+C.border,background:C.surface,color:C.text,fontSize:14,boxSizing:"border-box",outline:"none"};
  const row={display:"flex",alignItems:"center",gap:10,padding:"9px 4px",cursor:"pointer",borderBottom:"1px solid "+C.borderLight};
  const sub={fontSize:11,color:C.textMuted,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"};
  const nm={fontSize:13.5,color:C.text,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"};
  const parentName=a=>{const p=a.parentId?MOUNTAINS.find(x=>x.id===a.parentId):null;return p?p.name:"";};
  const cragName=r=>{const m=MOUNTAINS.find(x=>x.id===r.mountainId);return m?m.name:"";};
  const areas=useMemo(()=>qq?MOUNTAINS.filter(m=>m.areaType&&["world","country"].indexOf(m.areaType)<0&&fuzzyMatch(qq,m.name)&&(!scope||inArea(m.id,scope))).slice(0,40):[],[qq,scope]);
  const routes=useMemo(()=>qq?ROUTES.filter(r=>(fuzzyMatchAny(qq,r.name,areaPathNames(r.mountainId)))&&(!scope||inArea(r.mountainId,scope))).slice(0,60):[],[qq,scope]);
  return <div><div style={{display:"flex",gap:4,background:C.surface,border:"1px solid "+C.border,borderRadius:9,padding:3,marginBottom:8}}><div onClick={()=>setMode("areas")} style={tab(mode==="areas")}>{<Lbl s={"📍 Areas"}/>}</div><div onClick={()=>setMode("routes")} style={tab(mode==="routes")}>{<Lbl s={"Routes"}/>}</div></div><input aria-label={mode==="areas"?"Search areas, crags, peaks":"Search routes & boulders"} value={q} onChange={e=>setQ(e.target.value)} placeholder={mode==="areas"?"Search areas, crags, peaks…":"Search routes & boulders…"} style={fld}/>{qq?<div style={{marginTop:6,maxHeight:compact?"34vh":"46vh",overflowY:"auto",overscrollBehavior:"contain"}}>{mode==="areas"?(areas.length?areas.map(a=><div key={a.id} onClick={()=>onArea&&onArea(a)} style={row}><span style={{fontSize:16,flexShrink:0}}>{<Lbl s={"📍"}/>}</span><div style={{flex:1,minWidth:0}}><div style={nm}>{a.name}</div><div style={sub}>{(ATYPE[a.areaType]||a.areaType)+(parentName(a)?" · "+parentName(a):"")}</div></div>{addArea?<span style={{fontSize:12,fontWeight:700,color:C.blue,flexShrink:0}}>{"+ Add all"}</span>:null}</div>):<div style={{fontSize:13,color:C.textMuted,padding:"14px 4px",textAlign:"center"}}>{"No areas match."}</div>):(routes.length?routes.map(r=>{const on=sel.indexOf(r.id)>=0;return <div key={r.id} onClick={()=>onRoute&&onRoute(r)} style={row}>{selected?<span style={{width:18,height:18,borderRadius:5,border:"1.5px solid "+(on?C.blue:C.border),background:on?C.blueSolid:"transparent",color:"#fff",fontSize:12,display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>{on?"✓":""}</span>:null}<div style={{flex:1,minWidth:0}}><div style={nm}>{r.name}</div><div style={sub}>{cragName(r)}</div></div>{onView?<button onClick={e=>{e.stopPropagation();onView(r);}} style={{flexShrink:0,fontSize:10.5,fontWeight:700,color:C.blue,background:C.blueBg,border:"1px solid "+C.blueDim,borderRadius:7,padding:"3px 8px",cursor:"pointer"}}>{"Details"}</button>:null}<span style={{fontSize:12,color:C.textMuted,flexShrink:0,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{r.grade}</span></div>;}):<div style={{fontSize:13,color:C.textMuted,padding:"14px 4px",textAlign:"center"}}>{"No routes match."}</div>)}</div>:null}</div>;
}

const ATYPE={world:"World",country:"Country",state:"State",range:"Range",canyon:"Canyon",peak:"Peak",crag:"Crag",region:"Region",wall:"Wall"};
function areaClimbCount(areaId,disc,seen){seen=seen||new Set();if(seen.has(areaId))return 0;seen.add(areaId);let n=ROUTES.filter(r=>r.mountainId===areaId&&(!disc||disc==="All"||rDiscs(r).includes(disc))).length;MOUNTAINS.filter(m=>m.parentId===areaId).forEach(c=>{n+=areaClimbCount(c.id,disc,seen);});return n;}
