function areaCover(areaId){const d=ROUTES.find(r=>r.mountainId===areaId);if(d)return d.cover;for(const ch of MOUNTAINS.filter(m=>m.parentId===areaId)){const c=areaCover(ch.id);if(c)return c;}return null;}
