function revTime(d){var M={Jan:1,Feb:2,Mar:3,Apr:4,May:5,Jun:6,Jul:7,Aug:8,Sep:9,Oct:10,Nov:11,Dec:12};var q=(d||"").split(" ");return (parseInt(q[1])||0)*100+(M[q[0]]||0);}
function AvailCal({guide,value,onPick}){
  const today=new Date();today.setHours(0,0,0,0);
  const start=new Date(today);start.setDate(start.getDate()-start.getDay());
  const seed=String(guide.id||"g").split("").reduce((a,c)=>a+c.charCodeAt(0),0);
  const fmt=d=>d.toLocaleDateString(DLOCALE,{weekday:"short",month:"short",day:"numeric"});
  const DOW=["S","M","T","W","T","F","S"];
  const cells=[];for(let i=0;i<42;i++){const d=new Date(start);d.setDate(start.getDate()+i);cells.push(d);}
  const isPast=d=>d<today;
  const open=d=>{if(isPast(d))return false;const idx=Math.round((d-today)/86400000);return ((idx*7+seed)%10)>3;};
  return <div style={{marginBottom:12}}>
    <div style={{fontSize:12,color:C.textMuted,fontWeight:700,marginBottom:6,letterSpacing:0.3}}>PICK A DATE{value?<span style={{color:C.green,marginLeft:6}}>{" · "+value}</span>:null}</div>
    <div style={{display:"grid",gridTemplateColumns:"repeat(7,1fr)",gap:4,marginBottom:4}}>{DOW.map((d,i)=><div key={i} style={{textAlign:"center",fontSize:11,color:C.textMuted,fontWeight:700}}>{d}</div>)}</div>
    <div style={{display:"grid",gridTemplateColumns:"repeat(7,1fr)",gap:4}}>{cells.map((d,i)=>{const past=isPast(d),op=open(d),sel=value===fmt(d);return <button key={i} disabled={past||!op} onClick={()=>onPick(fmt(d))} style={{padding:"7px 0",borderRadius:8,border:"1px solid "+(sel?C.green:op?C.greenDim:"transparent"),background:sel?C.green:op?C.greenBg:"transparent",color:sel?C.bg:op?C.green:C.textMuted,fontSize:12,fontWeight:(sel||op)?"700":"400",cursor:(past||!op)?"default":"pointer",opacity:past?0.35:1}}>{d.getDate()}</button>;})}</div>
    <div style={{display:"flex",gap:14,marginTop:8,fontSize:11.5,color:C.textMuted,alignItems:"center"}}><span style={{display:"inline-flex",alignItems:"center",gap:4}}><span style={{width:9,height:9,borderRadius:2,background:C.greenBg,border:"1px solid "+C.greenDim}}/>Available</span><span style={{display:"inline-flex",alignItems:"center",gap:4}}><span style={{width:9,height:9,borderRadius:2,background:C.green}}/>Selected</span><span>Faded = unavailable</span></div>
  </div>;
}
