  {afChips.length?<div style={{display:"flex",gap:6,flexWrap:"wrap",alignItems:"center",marginBottom:9}}>{afChips.map(c=><button key={c.k} onClick={c.clear} style={{display:"inline-flex",alignItems:"center",gap:5,padding:"7px 10px 7px 12px",borderRadius:16,border:"1px solid "+C.blueDim,background:C.blueBg,color:C.blue,fontSize:12,fontWeight:700,cursor:"pointer"}}>{c.label}<span style={{opacity:0.7}}>{"✕"}</span></button>)}<button onClick={()=>setAf(DEF)} style={{padding:"5px 8px",background:"none",border:"none",color:C.textMuted,fontSize:12,fontWeight:700,cursor:"pointer",textDecoration:"underline"}}>{"Clear all"}</button></div>:null}<div style={{fontSize:11.5,color:C.textMuted,marginBottom:8,padding:"0 2px"}}>{list.length+" route"+(list.length!==1?"s":"")+" · sorted by "+({popular:"popularity",hard:"hardest",easy:"easiest",az:"A→Z",za:"Z→A"}[af.sort])}</div>
