    {(df.types.length===0||df.types.some(t=>NONPITCHED.indexOf(t)<0))?<>{lab("Pitches")}<div style={{display:"flex",gap:7,flexWrap:"wrap"}}>{[[0,"Any"],[1,"1+ (single)"],[2,"2+ (multi-pitch)"],[3,"3+"],[4,"4+"],[5,"5+"],[6,"6+"],[8,"8+"],[10,"10+"],[15,"15+"]].map(o=>chip(o[1],df.minPitches===o[0],()=>setDf(d=>({...d,minPitches:o[0]}))))}</div> {lab("Length")}<div style={{display:"flex",gap:7,flexWrap:"wrap"}}>{[["any","Any"],["u200","200 ft or less"],["200","201–600 ft"],["600","600–1500 ft"],["1500","1500+ ft"]].map(o=>chip(o[1],df.length===o[0],()=>setDf(d=>({...d,length:o[0]}))))}</div></>:null}
