  const list=comments.filter(c=>c.targetId===targetId&&!c.parentId).slice().sort((a,b)=>{const d=new Date(a.ts).getTime()-new Date(b.ts).getTime();return sort==="new"?-d:d;});
  const repliesFor=pid=>comments.filter(c=>c.parentId===pid).slice().sort((a,b)=>new Date(a.ts).getTime()-new Date(b.ts).getTime());
  const submit=()=>{const v=text.trim();if(!v)return;onAdd(targetId,v);setText("");};
